static_assert(0 + 8 <= ChannelReset4::kBlockLength);  // TransactTime @0
static_assert(8 + 1 <= ChannelReset4::kBlockLength);  // MatchEventIndicator @8
static_assert(ChannelReset4::NoMDEntries::kBlockLength == 2);
static_assert(ChannelReset4::NoMDEntries::kRequiredBlockLength <= ChannelReset4::NoMDEntries::kBlockLength);
static_assert(0 + 2 <= ChannelReset4::NoMDEntries::kBlockLength);  // ApplID @0

class ChannelReset4Writer {
 public:
  using Reader = ChannelReset4;
  // Writes the root block at the start of `body` (the bytes after the SBE message
  // header) and zero-fills it. Groups must be appended in schema order.
  explicit ChannelReset4Writer(std::span<std::byte> body) noexcept
      : p_(body.data()), cap_(body.size()), used_(Reader::kBlockLength) {
    if (cap_ < used_) {
      ok_ = false;
      used_ = 0;
      return;
    }
    std::memset(p_, 0, used_);
  }
  [[nodiscard]] bool ok() const noexcept { return ok_; }
  [[nodiscard]] std::size_t size_bytes() const noexcept { return used_; }
  [[nodiscard]] static constexpr sbe::MessageHeader header() noexcept {
    return sbe::MessageHeader{Reader::kBlockLength, Reader::kTemplateId, kSchemaId, kSchemaVersion};
  }
  void set_transact_time(std::uint64_t v) noexcept { sbe::store_le<std::uint64_t>(root() + 0, v); }
  void set_match_event_indicator(MatchEventIndicator v) noexcept { sbe::store_le<std::uint8_t>(root() + 8, v.bits); }
  // Appends the NoMDEntries group with `count` zero-filled entries.
  [[nodiscard]] sbe::GroupWriter<Reader::NoMDEntriesWriter, Reader::NoMDEntries::Dimension> no_md_entries(std::size_t count) noexcept {
    auto g = sbe::GroupWriter<Reader::NoMDEntriesWriter, Reader::NoMDEntries::Dimension>::create(ok_ ? p_ + used_ : nullptr, ok_ ? cap_ - used_ : 0, Reader::NoMDEntries::kBlockLength, count);
    if (g.ok()) {
      used_ += g.size_bytes();
    } else {
      ok_ = false;
    }
    return g;
  }

 private:
  [[nodiscard]] std::byte* root() noexcept { return ok_ ? p_ : scratch_; }
  std::byte* p_;
  std::size_t cap_;
  std::size_t used_;
  bool ok_ = true;
  std::byte scratch_[Reader::kBlockLength > 0 ? Reader::kBlockLength : 1] = {};
};

