class SnapshotFullRefresh52Writer {
 public:
  using Reader = SnapshotFullRefresh52;
  // Writes the root block at the start of `body` (the bytes after the SBE message
  // header) and zero-fills it. Groups must be appended in schema order.
  explicit SnapshotFullRefresh52Writer(std::span<std::byte> body) noexcept
      : p_(body.data()), cap_(body.size()), used_(Reader::kBlockLength) {
    if (cap_ < used_) {
      ok_ = false;
      used_ = 0;
      return;
    }
    std::memset(p_, 0, used_);
  }
  [[nodiscard]] bool ok() const noexcept { return ok_; }
  [[nodiscard]] std::size_t size_bytes() const noexcept { return used_; }
  [[nodiscard]] static constexpr sbe::MessageHeader header() noexcept {
    return sbe::MessageHeader{Reader::kBlockLength, Reader::kTemplateId, kSchemaId, kSchemaVersion};
  }
  void set_last_msg_seq_num_processed(std::uint32_t v) noexcept { sbe::store_le<std::uint32_t>(root() + 0, v); }
  void set_tot_num_reports(std::uint32_t v) noexcept { sbe::store_le<std::uint32_t>(root() + 4, v); }
  void set_security_id(std::int32_t v) noexcept { sbe::store_le<std::int32_t>(root() + 8, v); }
  void set_rpt_seq(std::uint32_t v) noexcept { sbe::store_le<std::uint32_t>(root() + 12, v); }
  void set_transact_time(std::uint64_t v) noexcept { sbe::store_le<std::uint64_t>(root() + 16, v); }
  void set_last_update_time(std::uint64_t v) noexcept { sbe::store_le<std::uint64_t>(root() + 24, v); }
  void set_trade_date(std::uint16_t v) noexcept { sbe::store_le<std::uint16_t>(root() + 32, v); }
  void set_md_security_trading_status(SecurityTradingStatus v) noexcept { sbe::store_le<std::uint8_t>(root() + 34, static_cast<std::uint8_t>(v)); }
  void set_high_limit_price(const PRICENULL9& v) noexcept { v.store(root() + 35); }
  void set_low_limit_price(const PRICENULL9& v) noexcept { v.store(root() + 43); }
  void set_max_price_variation(const PRICENULL9& v) noexcept { v.store(root() + 51); }
  // Appends the NoMDEntries group with `count` zero-filled entries.
  [[nodiscard]] sbe::GroupWriter<Reader::NoMDEntriesWriter, Reader::NoMDEntries::Dimension> no_md_entries(std::size_t count) noexcept {
    auto g = sbe::GroupWriter<Reader::NoMDEntriesWriter, Reader::NoMDEntries::Dimension>::create(ok_ ? p_ + used_ : nullptr, ok_ ? cap_ - used_ : 0, Reader::NoMDEntries::kBlockLength, count);
    if (g.ok()) {
      used_ += g.size_bytes();
    } else {
      ok_ = false;
    }
    return g;
  }

 private:
  [[nodiscard]] std::byte* root() noexcept { return ok_ ? p_ : scratch_; }
  std::byte* p_;
  std::size_t cap_;
  std::size_t used_;
  bool ok_ = true;
  std::byte scratch_[Reader::kBlockLength > 0 ? Reader::kBlockLength : 1] = {};
};

